TABLEATTRIBUTE.VALUE:
declare @MONTH int set @MONTH = (Select MAX(Loop_Nbr) from Run_Loop_Contrl where Table_Name ='Fact_Monthly_Acct' and is_Processed=0)
Select DM.ACCT_SK, DM.Infopro_Div_Nbr, DM.Acct_Nbr, DM.Acct_Open_Dt, DM.Acct_Close_Dt, /*** The data load is always for current month -1 by default. Extract YYYYMM format for date **/ Convert(INT,LEFT(REPLACE(CONVERT(varchar(50), DATEADD(month, -(@MONTH), GETDATE()), 102), '.', ''),6)) Acct_Month, /** Rank on Acct_SK for same Account to elemenate Dups ***/ ROW_NUMBER() OVER(PARTITION BY DM.Infopro_Div_Nbr, DM.Acct_Nbr ORDER BY ACCT_SK desc) RNum,
DM.Source_System FROM DIM_ACCT DM where /** Check if Acct was opened <= last day of the load month **/ DM.Acct_Open_Dt <= DATEADD(day,-1,convert(date,LEFT(CONVERT(varchar(50), DATEADD(month, -((@MONTH)-1), GETDATE()), 20),7)+'-01'))
/** Pull the appropriate record from the Acct ladder where last day of the load month between Eff and Disc dates **/ and DATEADD(day,-1,convert(date,LEFT(CONVERT(varchar(50), DATEADD(month, -((@MONTH)-1) , GETDATE()), 20),7)+'-01')) between DM.Eff_Dt AND DM.Disc_Dt
/** Pull the appropriate record from the Acct where its not a split/merge record **/ And (Exception_Batch_ID is NULL) --and DM.Infopro_Div_Nbr in ('015','046','902')

ATTRIBUTE.VALUE:
begin
MERGE DWCORE.dbo.Fact_Monthly_Acct AS fma USING (SELECT DISTINCT Monthly_Account_PK,Assigned_GL_Div_Nbr FROM DWCORE.dbo.ETL_FACT_MONTHLY_ACCT_UPd) UPD ON UPD.Monthly_Account_PK=FMA.Monthly_Account_PK WHEN MATCHED THEN UPDATE SET FMA.Assigned_GL_Div_Nbr=UPD.Assigned_GL_Div_Nbr\;
end;
